<?php $m=$member;$verify=!empty($m['verification_token'])?absolute_url('verify/member/'.$m['verification_token']):'';?><div class="page-actions"><div><h2>Member Profile</h2><p>Secure identity, account status and QR verification management.</p></div><div><a class="outline-link" href="<?=url('admin/members')?>">← Back</a></div></div><div class="admin-member-detail-grid"><section class="admin-panel member-identity-panel"><div class="member-detail-avatar"><?php if($m['profile_photo']):?><img src="<?=e(public_upload($m['profile_photo']))?>" alt="<?=e($m['name'])?>"><?php else:?><span><?=e(strtoupper(substr($m['name'],0,1)))?></span><?php endif;?></div><h3><?=e($m['name'])?></h3><div class="state-badges member-detail-state"><span class="status-badge <?=e($m['status'])?>"><?=e(ucfirst($m['status']))?></span><span class="member-public-state <?=((int)$m['is_public']===1&&$m['status']==='active')?'published':'private'?>"><?=((int)$m['is_public']===1&&$m['status']==='active')?'Published':'Private'?></span></div><div class="member-detail-id"><small>Member ID</small><strong><?=e($m['member_number']?:'—')?></strong></div><div class="admin-member-qr" data-qr-code data-qr-text="<?=e($verify)?>"></div><button class="outline-link" type="button" data-download-admin-qr data-name="<?=e($m['member_number']?:'member')?>">Download QR PNG</button><a class="outline-link" href="<?=e($verify)?>" target="_blank">Open Verification Page ↗</a></section><section class="admin-panel member-detail-info"><div class="panel-head"><h3>Personal & Account Information</h3></div><div class="member-detail-data"><p><small>Username</small><b><?=e($m['username']?:'—')?></b></p><p><small>Email</small><b><?=e($m['email'])?></b></p><p><small>Contact</small><b><?=e($m['mobile']?:'—')?></b></p><p><small>Date of Birth</small><b><?=e($m['date_of_birth']?date('d M Y',strtotime($m['date_of_birth'])):'—')?></b></p><p><small>NIC / National ID</small><b><?=e($m['nic_number']?:'—')?></b></p><p><small>Gender</small><b><?=e($m['gender']?ucwords(str_replace('_',' ',$m['gender'])):'—')?></b></p><p><small>Foundation Role</small><b><?=e($m['role_title']?:'Foundation Member')?></b></p><p><small>Member Since</small><b><?=e($m['joined_at']?date('d M Y',strtotime($m['joined_at'])):'—')?></b></p></div><div class="member-admin-status-actions"><form method="post" action="<?=url('admin/members/status')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$m['id']?>"><select name="status"><?php foreach(['active','pending','inactive','suspended','rejected'] as $st):?><option value="<?=$st?>" <?=$m['status']===$st?'selected':''?>><?=e(ucfirst($st))?></option><?php endforeach;?></select><input name="reason" maxlength="500" placeholder="Reason when rejecting"><button class="admin-btn">Update Membership Status</button></form></div><hr><div class="panel-head"><div><h3>Secure Password Reset</h3><span>Passwords are never displayed. Set a new temporary password of 8–12 characters.</span></div></div><form method="post" action="<?=url('admin/members/reset-password')?>" class="admin-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$m['id']?>"><label><span>New Password</span><input type="password" name="new_password" minlength="8" maxlength="12" required autocomplete="new-password"></label><label><span>Confirm Password</span><input type="password" name="password_confirmation" minlength="8" maxlength="12" required autocomplete="new-password"></label><button class="outline-link full">Reset Password Securely</button></form></section></div>